ent .= "return " . $export . ";\n"; return $content; } public static function loadMap(): ?array { $path = self::$outputFile; if (file_exists($path) && is_readable($path)) { return include $path; } return null; } } namespace RapidBase\Meta\Discovery; use PDO; class PostgreSQLDiscovery implements DiscoveryInterface { private PDO $pdo; public function __construct(PDO $pdo) { $this->pdo = $pdo; } public function discoverRelationships(string $databaseName): array { $graph = ['from' => [], 'to' => []]; $sql = "
