 VALUES (1, 'test')"); $stmt = $this->pdo->query("SELECT * FROM {$tempTable}"); } $stmt->fetchAll(PDO::FETCH_NUM); $reliable = true; for ($i = 0; $i < $stmt->columnCount(); $i++) { $meta = $stmt->getColumnMeta($i); if ($meta === false || !isset($meta['name']) || $meta['name'] === '*') { $reliable = false; break; } } if ($this->driver === 'sqlite') { $this->pdo->exec("DROP TABLE IF EXISTS temp.{$tempTable}"); } else { $this->pdo->exec("DROP TEMPORARY TABLE IF EXISTS {$tempTable}"); } return $reliable; } catch (\Throwable $e) { return false; } } private function probeNamedParameters(): bool { try { $stmt = $this->pdo->prepare("SELECT :val AS result"); $stmt->execute(['val' => 1]); $row = $stmt->fetch(PDO::FETCH_ASSOC); return isset($row['result']) && (int)$row['result'] === 1; } catch (\Throwable $e) { return false; } } private function probeNativeJson(): bool { return match ($this->driver) { 'mysql' => $this->safeProbe("SELECT JSON_OBJECT('key', 'value') AS j"), 'pgsql' => $this->safeProbe("SELECT '{}'::jsonb AS j"), 'sqlite' => $this->safeProbe("SELECT json('{}') AS j"), default => false, }; } private function probeAtomicUpsert(): bool { try { $tempTable = '_rb_upsert_probe_' . mt_rand(1000, 9999); if ($this->driver === 'sqlite') { $this->pdo->exec("CREATE TEMP TABLE {$tempTable} (id INTEGER PRIMARY KEY, val TEXT)"); $this->pdo->exec("INSERT INTO temp.{$tempTable} (id, val) VALUES (1, 'a')"); $sql = "INSERT INTO temp.{$tempTable} (id, val) VALUES (1, 'b') ON CONFLICT(id) DO UPDATE SET val=excluded.val"; } elseif ($this->driver === 'mysql') { $this->pdo->exec("CREATE TEMPORARY TABLE {$tempTable} (id INT PRIMARY KEY, val VARCHAR(10))"); $this->pdo->exec("INSERT INTO {$tempTable} (id, val) VALUES (1, 'a')"); $sql = "INSERT INTO {$tempTable} (id, val) VALUES (1, 'b') ON DUPLICATE KEY UPDATE val=VALUES(val)"; } elseif ($this->driver === 'pgsql') { $this->pdo->exec("CREATE TEMPORARY TABLE {$tempTable} (id INT PRIMARY KEY, val TEXT)"); $this->pdo->exec("INSERT INTO {$tempTable} (id, val) VALUES (1, 'a')"); $sql = "INSERT INTO {$tempTable} (id, val) VALUES (1, 'b') ON CONFLICT(id) DO UPDATE SET val=EXCLUDED.val"; } else { return false; } $this->pdo->exec($sql); $finalVal = $this->pdo->query("SELECT val FROM " . ($this->driver === 'sqlite' ? "temp." : "") . "{$tempTable} WHERE id=1")->fetchColumn(); if ($this->driver === 'sqlite') { $this->pdo->exec("DROP TABLE IF EXISTS temp.{$tempTable}"); } else { $this->pdo->exec("DROP TEMPORARY TABLE IF EXISTS {$tempTable}"); } return $finalVal === 'b'; } catch (\Throwable $e) { return false; } } private function probeCTE(): bool { return $this->safeProbe("WITH _cte AS (SELECT 1 AS n) SELECT n FROM _cte"); } private function probeReturning(): bool { return match ($this->driver) { 'pgsql' => true, 'sqlite' => $this->isVersionAtLeast('3.35.0'), 'mysql' => false, default => false, }; } private function probeTransactions(): bool { try { return $this->pdo->getAttribute(PDO::ATTR_DRIVER_NAME) !== 'sqlite' || $this->pdo->query("SELECT 1")->execute(); } catch (\Throwable $e) { return false; } } private function probeSavepoints(): bool { try { $this->pdo->exec("SAVEPOINT _probe_sp"); $this->pdo->exec("RELEASE SAVEPOINT _probe_sp"); return true; } catch (\Throwable $e) { return false; } } private function probeLimitOnUpdateDelete(): bool { return match ($this->driver) { 'mysql' => true, default => false, }; } private function safeProbe(string $sql): bool { try { $stmt = $this->pdo->query($sql); $stmt->fetchAll(); return true; } catch (\Throwable $e) { return false; } } private function isVersionAtLeast(string $minVersion): bool { $current = $this->detectVersion(); if (preg_match('/^(\d+\.\d+\.\d+)/', $current, $m)) { return version_compare($m[1], $minVersion, '>='); } return false; } } namespace RapidBase\Meta\Discovery; interface DiscoveryInterface { public function discoverRelationships(string $databaseName): array; public function discoverColumns(string $tableName, string $databaseName): array; public function discoverPrimaryKey(string $tableName, string $databaseName): ?string; public function getTables(string $databaseName): array; } namespace RapidBase\Meta\Discovery; use PDO; class SQLiteDiscovery implements DiscoveryInterface { private PDO $pdo; public function __construct(PDO $pdo) { $this->pdo = $pdo; } public function discoverRelationships(string $databaseName): array { $graph = ['from' => [], 'to' => []]; $tables = $this->getTables($databaseName); foreach ($tables as $table) { $fks = $this->getForeignKeys($table); foreach ($fks as $fk) { $sourceTable = $table; $targetTable = $fk['table']; $sourceColumn = $fk['from']; $targetColumn = $fk['to']; if (!isset($graph['from'][$sourceTable])) { $graph['from'][$sourceTable] = []; } if (!isset($graph['from'][$sourceTable][$targetTable])) { $graph['from'][$sourceTable][$targetTable] = []; } $graph['from'][$sourceTable][$targetTable][$sourceColumn] = $targetColumn; if (!isset($graph['to'][$targetTable])) { $graph['to'][$targetTable] = []; } if (!isset($graph['to'][$targetTable][$sourceTable])) { $graph['to'][$targetTable][$sourceTable] = []; } $graph['to'][$targetTable][$sourceTable][$targetColumn] = $sourceColumn; } } return $graph; } public function getTables(string $databaseName = 'main'): array { $sql = "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"; $stmt = $this->pdo->query($sql); return $stmt->fetchAll(PDO::FETCH_COLUMN); } public function getColumns(string $table): array { $columns = []; $stmt = $this->pdo->query("PRAGMA table_info('$table')"); $result = $stmt->fetchAll(PDO::FETCH_ASSOC); foreach ($result as $col) { $colName = $col['name']; $columns[$colName] = [ 'type' => $col['type'] ?? 'TEXT', 'primary' => (bool)$col['pk'], 'foreign' => false, 'nullable' => !(bool)$col['notnull'], 'default' => $col['dflt_value'], 'references' => null, 'description' => null ]; } $fks = $this->getForeignKeys($table); foreach ($fks as $fk) { if (isset($columns[$fk['from']])) { $c