				INFORMATION_SCHEMA.KEY_COLUMN_USAGE KCU
			JOIN
				INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS RC
				ON KCU.CONSTRAINT_NAME = RC.CONSTRAINT_NAME
				AND KCU.TABLE_SCHEMA = RC.CONSTRAINT_SCHEMA
			WHERE
				KCU.TABLE_SCHEMA = :databaseName
				AND KCU.REFERENCED_TABLE_NAME IS NOT NULL
			ORDER BY
				KCU.TABLE_NAME, KCU.COLUMN_NAME;"; $stmt = $this->pdo->prepare($sql); $stmt->bindParam(':databaseName', $databaseName, PDO::PARAM_STR); $stmt->execute(); $results = $stmt->fetchAll(PDO::FETCH_ASSOC); foreach ($results as $row) { $sourceTable = $row['source_table']; $targetTable = $row['target_table']; $sourceColumn = $row['source_column']; $targetColumn = $row['target_column']; $graph['from'][$sourceTable][$targetTable] = [ 'type' => 'belongsTo', 'local_key' => $sourceColumn, 'foreign_key' => $targetColumn, ]; $graph['to'][$targetTable][$sourceTable] = [ 'type' => 'hasMany', 'local_key' => $sourceColumn, 'foreign_key' => $targetColumn, ]; } return $graph; } public static function getSchemaSignature(PDO $pdo, string $databaseName): string { $sql = "SELECT md5(group_concat(table_name, update_time)) 
				FROM information_schema.tables 
				WHERE table_schema = :db"; $stmt = $pdo->prepare($sql); $stmt->execute(['db' => $databaseName]); return $stmt->fetchColumn() ?: ''; } public function discoverColumns(string $tableName, string $databaseName): array { $columns = []; $sql = "
			SELECT 
				C.COLUMN_NAME, 
				C.DATA_TYPE, 
				C.COLUMN_KEY, 
				C.IS_NULLABLE, 
				C.COLUMN_DEFAULT,
				KCU.REFERENCED_TABLE_NAME,
				KCU.REFERENCED_COLUMN_NAME
			FROM INFORMATION_SCHEMA.COLUMNS C
			LEFT JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE KCU 
				ON C.TABLE_SCHEMA = KCU.TABLE_SCHEMA 
				AND C.TABLE_NAME = KCU.TABLE_NAME 
				AND C.COLUMN_NAME = KCU.COLUMN_NAME
				AND KCU.REFERENCED_TABLE_NAME IS NOT NULL
			WHERE C.TABLE_SCHEMA = :databaseName 
			  AND C.TABLE_NAME = :tableName
			ORDER BY C.ORDINAL_POSITION"; $stmt = $this->pdo->prepare($sql); $stmt->execute(['databaseName' => $databaseName, 'tableName' => $tableName]); while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) { $columns[$row['COLUMN_NAME']] = [ 'type' => $row['DATA_TYPE'], 'primary' => ($row['COLUMN_KEY'] === 'PRI'), 'foreign' => !is_null($row['REFERENCED_TABLE_NAME']), 'nullable' => ($row['IS_NULLABLE'] === 'YES'), 'default' => $row['COLUMN_DEFAULT'], 'references' => $row['REFERENCED_TABLE_NAME'] ? [ 'table' => $row['REFERENCED_TABLE_NAME'], 'column' => $row['REFERENCED_COLUMN_NAME'] ] : null, ]; } return $columns; } public function discoverPrimaryKey(string $tableName, string $databaseName): ?string { $sql = "
			SELECT COLUMN_NAME
			FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE
			WHERE TABLE_SCHEMA = :databaseName
			  AND TABLE_NAME = :tableName
			  AND CONSTRAINT_NAME = 'PRIMARY'
			ORDER BY ORDINAL_POSITION;"; $stmt = $this->pdo->prepare($sql); $stmt->bindParam(':databaseName', $databaseName, PDO::PARAM_STR); $stmt->bindParam(':tableName', $tableName, PDO::PARAM_STR); $stmt->execute(); $result = $stmt->fetch(PDO::FETCH_ASSOC); if ($result) { $pkCols = [$result['COLUMN_NAME']]; $more = $stmt->fetchAll(PDO::FETCH_ASSOC); foreach ($more as $row) { $pkCols[] = $row['COLUMN_NAME']; } return count($pkCols) === 1 ? $pkCols[0] : $pkCols; } return null; } public function getTables(string $databaseName): array { $sql = "SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = :databaseName AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME"; $stmt = $this->pdo->prepare($sql); $stmt->bindParam(':databaseName', $databaseName, PDO::PARAM_STR); $stmt->execute(); return $stmt->fetchAll(PDO::FETCH_COLUMN); } } 
// ApiContext class for RapidBase API
namespace RapidBase\Api;

class ApiContext {
    public function __construct(
        public array $params = [],
        public array $session = [],
        public array $auth = []
    ) {}
}

// BaseEndpoint class for RapidBase API
namespace RapidBase\Api;

use ReflectionClass;
use ReflectionMethod;

abstract class BaseEndpoint {
    protected ApiContext $context;

    public function setContext(ApiContext $context): void {
        $this->context = $context;
    }

    public function describe(): array {
        $reflection = new ReflectionClass($this);
        $methods = $reflection->getMethods(ReflectionMethod::IS_PUBLIC);
        $manifest = [];

        foreach ($methods as $method) {
            if ($method->class === self::class || str_starts_with($method->name, '__')) {
                continue;
            }

            $manifest[$method->name] = [
                'description' => $this->parseDoc($method->getDocComment()),
                'parameters'  => array_map(fn($p) => [
                    'name'     => $p->getName(),
                    'type'     => $p->hasType() ? $p->getType()->getName() : 'mixed',
                    'optional' => $p->isOptional()
                ], $method->getParameters())
            ];
        }

        return $manifest;
    }

    public function version(): array {
        return [
            'endpoint' => static::class,
            'version' => '1.0.0'
        ];
    }

    public function catalog(): array {
        return [
            'endpoint' => static::class,
            'methods' => array_keys($this->describe())
        ];
    }

    private function parseDoc($doc): string {
        return trim(preg_replace('/(\/\*\*|\*\/|\*)/', '', (string)$doc));
    }
}
